<script setup lang="ts">import {ref,onMounted} from 'vue';import {modelsStore} from '../stores/models';import {datasetsStore} from '../stores/datasets';import {create} from '../api/models';import {create as createRun} from '../api/runs';import {canEdit} from '../stores/auth';import {useTask} from '../hooks/useTask';import {useRouter} from 'vue-router';import PageTitle from '../components/common/PageTitle.vue';import Notice from '../components/common/Notice.vue';const {items,error,reload}=modelsStore(),datasets=datasetsStore(),router=useRouter();const form=ref({name:'城北漏损优先 · 新推演',dataset_id:'data-demo',false_negative_cost:25,false_positive_cost:1,daily_budget:40,seed:42});const {busy,error:taskError,execute}=useTask();onMounted(async()=>{await Promise.all([reload(),datasets.reload()])});function run(id:string){execute(async()=>{const r=await createRun({model_id:id});router.push('/results?run='+r.id)})}function submit(){execute(async()=>{const m=await create(form.value);await reload();const r=await createRun({model_id:m.id});router.push('/results?run='+r.id)})}</script><template><PageTitle eyebrow="03 / MODEL REHEARSAL" title="把巡检偏好，写进成本。" description="分层交叉验证选择正则强度，独立留出集衡量效果。参数调整会保留为新的配置与运行记录。"/><Notice :error="error||taskError"/><div class="split-layout"><section><div class="section-heading"><h2>已有试验配置</h2><span>{{items.length}} 个版本</span></div><article class="model-row" v-for="m in items" :key="m.id"><div class="eyebrow mono">{{m.id}}</div><h2>{{m.name}}</h2><div class="model-meta"><span>漏检成本 <b>{{m.false_negative_cost}}</b></span><span>误检成本 <b>{{m.false_positive_cost}}</b></span><span>每日预算 <b>{{m.daily_budget}} 段</b></span></div><button :disabled="busy||!canEdit" @click="run(m.id)">按此配置运行 ↗</button></article><div class="method-note"><b>验证边界</b><p>75% 用于分层四折验证与阈值选择；25% 留出评价。概率经完整样本重拟合后形成巡检排序，不回写独立评价指标。</p></div></section><section class="form-panel"><div class="eyebrow">NEW REHEARSAL</div><h2>建立新的成本情景</h2><form @submit.prevent="submit"><label>配置名称<input v-model="form.name" minlength="2" required :disabled="!canEdit"></label><label>样本批次<select v-model="form.dataset_id" :disabled="!canEdit"><option v-for="d in datasets.items.value" :key="d.id" :value="d.id">{{d.name}}</option></select></label><div class="form-pair"><label>漏检成本<input v-model.number="form.false_negative_cost" type="number" min="0.1" max="10000" step="0.1" required :disabled="!canEdit"></label><label>误检成本<input v-model.number="form.false_positive_cost" type="number" min="0.1" max="10000" step="0.1" required :disabled="!canEdit"></label></div><label>每日最多巡检管段<input v-model.number="form.daily_budget" type="number" min="1" max="5000" required :disabled="!canEdit"></label><label>随机种子<input v-model.number="form.seed" type="number" min="0" max="2147483647" required :disabled="!canEdit"></label><button class="primary" :disabled="busy||!canEdit">{{busy?'提交中…':'保存并开始训练 →'}}</button></form></section></div></template>
